cat > /tmp/parse_npcs.ts <<'EOF'
import { readdirSync, readFileSync } from 'fs';
const dir = 'wiki/npcs';
const rows: any[] = [];
for (const f of readdirSync(dir)) {
  if (!f.endsWith('.md')) continue;
  const t = readFileSync(dir + '/' + f, 'utf8');
  const name = f.replace('.md','');
  const lvl = t.match(/\*\*Combat Level\*\* \| ([^\n|]+)/);
  const hp = t.match(/\*\*Hitpoints\*\* \| ([^\n|]+)/);
  const atkB = t.match(/Attack Bonus \| (-?\d+)/);
  const strB = t.match(/Strength Bonus \| (-?\d+)/);
  const sDef = t.match(/Slash Defence \| (-?\d+)/);
  const cDef = t.match(/Crush Defence \| (-?\d+)/);
  if (!lvl || !hp) continue;
  const ln = lvl[1].trim(), hn = hp[1].trim();
  const lmin = parseInt(ln.split('-')[0]), lmax = parseInt(ln.split('-')[1]||ln.split('-')[0]);
  const hmin = parseInt(hn.split('-')[0]), hmax = parseInt(hn.split('-')[1]||hn.split('-')[0]);
  rows.push({name, ln, hn, lmin, lmax, hmin, hmax, sDef: sDef?+sDef[1]:null, cDef: cDef?+cDef[1]:null});
}
rows.sort((a,b)=> (b.lmax) - (a.lmax));
for (const r of rows.slice(0,120)) console.log(`${r.name}\tlvl=${r.ln}\thp=${r.hn}\tslashDef=${r.sDef}`);
EOF
