import { readdirSync, readFileSync } from 'fs';
const dir = 'wiki/npcs';
const rows: any[] = [];
for (const f of readdirSync(dir)) {
  if (!f.endsWith('.md')) continue;
  const t = readFileSync(dir + '/' + f, 'utf8');
  const name = f.replace('.md','');
  const lvl = t.match(/\*\*Combat Level\*\* \| ([^\n|]+)/);
  const hp = t.match(/\*\*Hitpoints\*\* \| ([^\n|]+)/);
  const sd = t.match(/Slash Defence \| (-?\d+)/);
  const cd = t.match(/Crush Defence \| (-?\d+)/);
  const st = t.match(/Stab Defence \| (-?\d+)/);
  if (!lvl || !hp) continue;
  const lmax = parseInt(lvl[1].split('-').pop()!);
  const hmax = parseInt(hp[1].split('-').pop()!);
  if (isNaN(lmax)||isNaN(hmax)) continue;
  const defs = [sd,cd,st].map(m=>m?+m[1]:99);
  const mindef = Math.min(...defs);
  const locs = (t.split('## Locations')[1]?.split('## Drops')[0]||'').split('\n').filter(l=>l.includes('|')).slice(0,3).map(l=>l.trim()).join(' ; ');
  rows.push({name, lmax, hmax, mindef, locs});
}
// high level, low def, decent HP
const cand = rows.filter(r=>r.lmax>=25 && r.mindef<=5 && r.hmax>=20).sort((a,b)=>b.lmax-a.lmax);
for (const r of cand.slice(0,60)) console.log(`L${r.lmax}\tHP${r.hmax}\tdef${r.mindef}\t${r.name}\t${r.locs}`);
EOF
