import { readdirSync, readFileSync } from 'fs';
const dir='wiki/npcs';
const LUM={x:3222,z:3222};
const rows:any[]=[];
for(const f of readdirSync(dir)){
  if(!f.endsWith('.md'))continue;
  const t=readFileSync(dir+'/'+f,'utf8');
  const name=f.replace('.md','');
  const lvl=t.match(/\*\*Combat Level\*\* \| ([^\n|]+)/);
  const hp=t.match(/\*\*Hitpoints\*\* \| ([^\n|]+)/);
  const sd=t.match(/Slash Defence \| (-?\d+)/);
  const cd=t.match(/Crush Defence \| (-?\d+)/);
  const st=t.match(/Stab Defence \| (-?\d+)/);
  if(!lvl||!hp)continue;
  const lmax=parseInt(lvl[1].split('-').pop()!); const hmax=parseInt(hp[1].split('-').pop()!);
  if(isNaN(lmax)||isNaN(hmax))continue;
  const mindef=Math.min(...[sd,cd,st].map(m=>m?+m[1]:99));
  // gather coords from locations section
  const locsec=t.split('## Locations')[1]?.split('## Drops')[0]||'';
  const coords=[...locsec.matchAll(/\((\d{3,4}),\s*(\d{3,5})\)/g)].map(m=>({x:+m[1],z:+m[2]}));
  const over=coords.filter(c=>c.z<6000);
  let best=Infinity, bc=null;
  for(const c of over){const d=Math.hypot(c.x-LUM.x,c.z-LUM.z); if(d<best){best=d;bc=c;}}
  if(bc) rows.push({name,lmax,hmax,mindef,best:Math.round(best),bc});
}
// strongest reachable: level>=25, low def, nearest
const cand=rows.filter(r=>r.lmax>=25 && r.mindef<=5).sort((a,b)=>a.best-b.best);
for(const r of cand.slice(0,40)) console.log(`L${r.lmax} HP${r.hmax} def${r.mindef} dist${r.best} ${r.name} @(${r.bc.x},${r.bc.z})`);
EOF
